paired.runner_source:
$ErrorActionPreference = 'Stop'
$taskRepo = (Resolve-Path (Join-Path $PSScriptRoot '../..')).Path
$taskOutput = Join-Path $PSScriptRoot 'paired-evidence.json'
if (Test-Path -LiteralPath $taskOutput) { throw 'Refuse to overwrite paired measurements' }
if (Get-Process rustc -ErrorAction SilentlyContinue) { throw 'Do not benchmark during compilation' }
$taskExecutables = @{}
foreach ($taskVariant in @('baseline','current')) {
    $taskPath = Join-Path $PSScriptRoot ($taskVariant + '-paired.exe')
    $taskExecutables[$taskVariant] = [ordered]@{path=$taskPath;sha256=(Get-FileHash -LiteralPath $taskPath).Hash}
}
if ($taskExecutables.baseline.sha256 -eq $taskExecutables.current.sha256) { throw 'Refuse identical baseline/current binaries' }
$taskWhole = [Diagnostics.Stopwatch]::StartNew()
function Read-Event($taskProcess, $taskExpected) {
    $taskRemaining = [int][Math]::Min(5000, (20 - $taskWhole.Elapsed.TotalSeconds) * 1000)
    if ($taskRemaining -le 0) { throw 'Twenty-second paired experiment limit reached' }
    $taskRead = $taskProcess.StandardOutput.ReadLineAsync()
    if (-not $taskRead.Wait($taskRemaining)) { throw 'Timed out waiting for probe event' }
    $taskLine = $taskRead.GetAwaiter().GetResult()
    if (-not $taskLine) { throw "Probe ended: $($taskProcess.StandardError.ReadToEnd())" }
    $taskEvent = $taskLine | ConvertFrom-Json
    if ($taskEvent.event -ne $taskExpected) { throw "Expected $taskExpected, got $($taskEvent.event)" }
    return $taskEvent
}
function Invoke-Step($taskProcess, $taskCommand, $taskExpected) {
    $taskProcess.StandardInput.WriteLine($taskCommand)
    $taskProcess.StandardInput.Flush()
    Read-Event $taskProcess $taskExpected
}
$taskRecords = @()
$taskSpent = @{baseline=0.0;current=0.0}
foreach ($taskCase in @(@('medium','imgs_00018069','baseline'),@('tiny','imgs_1','current'))) {
    $taskProcesses = @{}
    $taskTimers = @{}
    $taskReady = @{}
    $taskWarmups = @{}
    $taskSamples = @{baseline=@();current=@()}
    $taskReports = @{}
    $taskFirst = $taskCase[2]
    $taskSecond = if ($taskFirst -eq 'baseline') { 'current' } else { 'baseline' }
    try {
        foreach ($taskVariant in @($taskFirst,$taskSecond)) {
            $taskInfo = [Diagnostics.ProcessStartInfo]::new()
            $taskInfo.FileName = $taskExecutables[$taskVariant].path
            $taskInfo.WorkingDirectory = $taskRepo
            $taskInfo.UseShellExecute = $false
            $taskInfo.CreateNoWindow = $true
            $taskInfo.RedirectStandardInput = $true
            $taskInfo.RedirectStandardOutput = $true
            $taskInfo.RedirectStandardError = $true
            $taskInfo.Environment['SIMD_OCR_PROBE_ROOT'] = $taskRepo
            foreach ($taskArg in @('--paired',$taskCase[0],$taskCase[1],'0','1')) { $taskInfo.ArgumentList.Add($taskArg) }
            $taskTimers[$taskVariant] = [Diagnostics.Stopwatch]::StartNew()
            $taskProcess = [Diagnostics.Process]::Start($taskInfo)
            $taskProcesses[$taskVariant] = $taskProcess
            $taskReady[$taskVariant] = Read-Event $taskProcess 'ready'
        }
        foreach ($taskProperty in @('model','fixture','affinity','pixel_sha256','manifest_sha256')) {
            if ($taskReady.baseline.$taskProperty -ne $taskReady.current.$taskProperty) { throw "Configuration mismatch: $taskProperty" }
        }
        foreach ($taskVariant in @($taskFirst,$taskSecond)) {
            $taskWarmups[$taskVariant] = Invoke-Step $taskProcesses[$taskVariant] 'warmup' 'warmup'
        }
        if ($taskWarmups.baseline.output_sha256 -ne $taskWarmups.current.output_sha256) { throw 'Warm-up output mismatch' }
        $taskOrder = @()
        for ($taskRound=0; $taskRound -lt 3; $taskRound++) {
            $taskSequence = if ($taskRound % 2 -eq 0) { @($taskFirst,$taskSecond) } else { @($taskSecond,$taskFirst) }
            $taskOrder += ,$taskSequence
            foreach ($taskVariant in $taskSequence) {
                $taskEvent = Invoke-Step $taskProcesses[$taskVariant] 'run' 'sample'
                if ($taskEvent.sample_index -ne $taskRound -or $taskEvent.output_sha256 -ne $taskWarmups.baseline.output_sha256) { throw 'Sample number or output mismatch' }
                $taskSamples[$taskVariant] += $taskEvent
                Write-Output "$($taskCase[0]) round=$taskRound $taskVariant $($taskEvent.milliseconds) ms"
            }
        }
        foreach ($taskVariant in @($taskFirst,$taskSecond)) {
            $taskProcess = $taskProcesses[$taskVariant]
            $taskReports[$taskVariant] = Read-Event $taskProcess 'complete'
            if (-not $taskProcess.WaitForExit(1000) -or $taskProcess.ExitCode -ne 0) { throw 'Probe did not exit successfully' }
            $taskTimers[$taskVariant].Stop()
            $taskSpent[$taskVariant] += $taskTimers[$taskVariant].Elapsed.TotalSeconds
            if (-not $taskReports[$taskVariant].complete_owned_outputs_exactly_equal) { throw 'Missing output parity' }
        }
        $taskRecords += [ordered]@{case=$taskCase[0..1];ready=$taskReady;warmups=$taskWarmups;order=$taskOrder;samples=$taskSamples;reports=$taskReports}
    } finally {
        foreach ($taskProcess in $taskProcesses.Values) {
            if (-not $taskProcess.HasExited) { $taskProcess.Kill(); $taskProcess.WaitForExit() }
            $taskProcess.Dispose()
        }
    }
}
[ordered]@{
    schema_version=1;timestamp=(Get-Date).ToString('o');git_head=(git -C $taskRepo rev-parse HEAD).Trim()
    scope='Two real pages, Medium dense and Tiny sparse; CPU24, one warm-up and three measured owned-result calls per version/case. Adjacent alternating baseline/current calls; no overlapping inference. Two processes resident together, one idle while the other runs.'
    total_experiment_seconds=$taskWhole.Elapsed.TotalSeconds;experiment_limit_seconds=20;conservative_process_seconds=$taskSpent
    executables=$taskExecutables;cases=$taskRecords;runner_source=[IO.File]::ReadAllText($PSCommandPath)
} | ConvertTo-Json -Depth 100 | Set-Content -LiteralPath $taskOutput
Write-Output "Conservative process seconds: baseline=$($taskSpent.baseline), current=$($taskSpent.current)"

model_census.parser_source:
"""Read-only ONNX structural census; no inference or timing loops."""
import hashlib
import json
from pathlib import Path

root = Path(__file__).resolve().parents[2]
models = root.parent / 'SimdPaddleOCR/models'

def varint(data, pos):
    result = shift = 0
    while True:
        value = data[pos]
        pos += 1
        result |= (value & 127) << shift
        if value < 128:
            return result, pos
        shift += 7
        assert shift < 70

def fields(data):
    pos = 0
    while pos < len(data):
        tag, pos = varint(data, pos)
        number, wire = tag >> 3, tag & 7
        if wire == 0:
            value, pos = varint(data, pos)
        elif wire == 2:
            size, pos = varint(data, pos)
            value = data[pos:pos+size]
            pos += size
        elif wire in (1, 5):
            size = 8 if wire == 1 else 4
            value = data[pos:pos+size]
            pos += size
        else:
            raise ValueError(f'unsupported wire type {wire}')
        assert pos <= len(data)
        yield number, wire, value

def integers(wire, value):
    if wire == 0:
        return [value]
    assert wire == 2
    values, pos = [], 0
    while pos < len(value):
        item, pos = varint(value, pos)
        values.append(item)
    return values

rows = []
for name in ['medium_det.onnx', 'medium_rec.onnx', 'cls.onnx', 'det.onnx', 'rec.onnx']:
    data = (models / name).read_bytes()
    graph = next(v for n,w,v in fields(memoryview(data)) if n == 7 and w == 2)
    weights, nodes = {}, []
    for number, wire, value in fields(graph):
        if number == 5:
            dims, key = [], None
            for n,w,v in fields(value):
                if n == 1:
                    dims.extend(integers(w,v))
                elif n == 8:
                    key = bytes(v).decode()
            weights[key] = dims
        elif number == 1:
            nodes.append(value)
    convs, shape_counts = [], {}
    for index, value in enumerate(nodes):
        inputs, attrs, op = [], {}, None
        for n,w,v in fields(value):
            if n == 1:
                inputs.append(bytes(v).decode())
            elif n == 4:
                op = bytes(v).decode()
            elif n == 5:
                key, values, string_value = None, [], None
                for an,aw,av in fields(v):
                    if an == 1:
                        key = bytes(av).decode()
                    elif an in (3,8):
                        values.extend(integers(aw,av))
                    elif an == 4:
                        string_value = bytes(av).decode()
                attrs[key] = string_value if string_value is not None else values
        if op != 'Conv':
            continue
        dims = weights[inputs[1]]
        assert len(dims) == 4
        shape = attrs.get('kernel_shape', dims[2:])
        assert shape == dims[2:]
        key = 'x'.join(map(str, shape))
        shape_counts[key] = shape_counts.get(key,0) + 1
        if shape == [2,2]:
            convs.append(dict(node=index, weights=dims, attributes=attrs))
    rows.append(dict(file=name, sha256=hashlib.sha256(data).hexdigest(),
                     conv_kernel_counts=shape_counts, conv_2x2=convs))
report = dict(scope='ONNX graph metadata only. ConvTranspose is a separate operator and does not enter nchw::PadEnd2.',
              models=rows, parser_source=Path(__file__).read_text(encoding='utf-8'))
(Path(__file__).parent/'model-census.json').write_text(json.dumps(report,indent=2)+'\n',encoding='utf-8')
print(json.dumps(rows,indent=2))

harness_source:
//! Fixed-count recognition ownership comparison on one 24-thread CPU context.
#[path = "../tools/baseline/mod.rs"]
mod baseline;
#[path = "../tools/benchmark/mod.rs"]
mod benchmark;

use baseline::{read_json, Manifest, Result};
use simd_paddle_ocr_rs::{
    cpu::{CpuContext, CpuOptions},
    detector::DetectorOptions,
    image::{ImageView, PixelFormat},
    lines::LineOptions,
    recognizer::RecognizerOptions,
    OcrModelSet,
};
use std::{io::Write, path::PathBuf, sync::Arc, time::Instant};

const CAPACITY: usize = 24;

fn event(value: &serde_json::Value) -> Result<()> {
    println!("{}", serde_json::to_string(value)?);
    std::io::stdout().flush()?;
    Ok(())
}

fn command(expected: &str) -> Result<()> {
    let mut line = String::new();
    if std::io::stdin().read_line(&mut line)? == 0 || line.trim() != expected {
        return Err(format!("paired probe expected {expected:?} on stdin").into());
    }
    Ok(())
}

fn check_deadline(started: Instant) -> Result<()> {
    if started.elapsed().as_secs_f64() >= 15. {
        return Err("fixed ownership probe exceeded fifteen seconds".into());
    }
    Ok(())
}

fn run() -> Result<()> {
    if cfg!(debug_assertions) || cfg!(feature = "profiling") || !cfg!(feature = "parallel") {
        return Err("use --release with default features and without profiling".into());
    }
    let mut args: Vec<_> = std::env::args().skip(1).collect();
    let paired = args.first().is_some_and(|arg| arg == "--paired");
    if paired {
        args.remove(0);
    }
    if args
        .first()
        .is_some_and(|arg| arg == "--help" || arg == "-h")
    {
        println!(
            "cargo run --release --locked --example cpu_owner_probe -- [tiny|small|medium] [FIXTURE] [OWNERS] [BATCH_SIZES]\nOWNERS is a comma-separated list of up to three budgets in 0..=16; default 0,12,16 (zero is automatic). BATCH_SIZES is one to three comma-separated sizes in 1..=4; default 1. One shared 24-thread CPU context; first 24 allowed Windows CPUs. One warm-up and three measured owned-result calls each. Exact complete output equality required. Fifteen-second internal deadline; also enforce an external timeout."
        );
        println!(
            "Optional --paired prefix enables a JSON-lines protocol for one owner/batch configuration: ready -> stdin warmup -> warmup result -> three stdin run commands/sample results -> complete report. No inference runs while waiting for commands. SIMD_OCR_PROBE_ROOT can select the common repository data root when comparing source snapshots. Enforce an external deadline including waits."
        );
        return Ok(());
    }
    if args.len() > 4 {
        return Err("expected MODEL FIXTURE OWNERS [BATCH_SIZES]; use --help".into());
    }
    let owners = args
        .get(2)
        .map_or("0,12,16", String::as_str)
        .split(',')
        .map(str::parse::<usize>)
        .collect::<std::result::Result<Vec<_>, _>>()?;
    if owners.is_empty() || owners.len() > 3 || owners.iter().any(|&count| count > 16) {
        return Err("expected one to three owner budgets in 0..=16".into());
    }
    let batch_sizes = args
        .get(3)
        .map_or("1", String::as_str)
        .split(',')
        .map(str::parse::<usize>)
        .collect::<std::result::Result<Vec<_>, _>>()?;
    if batch_sizes.is_empty()
        || batch_sizes.len() > 3
        || batch_sizes.iter().any(|size| !(1..=4).contains(size))
    {
        return Err("expected one to three batch sizes in 1..=4".into());
    }
    if paired && (owners.len() != 1 || batch_sizes.len() != 1) {
        return Err("paired mode requires exactly one owner and batch configuration".into());
    }
    let started = Instant::now();
    let model = args.first().map_or("medium", String::as_str);
    let fixture = args.get(1).map_or("imgs_00018069", String::as_str);
    let affinity = benchmark::platform::affinity(CAPACITY, None)?;
    benchmark::platform::configure(&affinity)?;
    let root = std::env::var_os("SIMD_OCR_PROBE_ROOT")
        .map(PathBuf::from)
        .unwrap_or_else(|| PathBuf::from(env!("CARGO_MANIFEST_DIR")));
    let manifest_path = root.join("tests/baseline/manifest.json");
    let manifest: Manifest = read_json(&manifest_path)?;
    manifest.validate()?;
    let directory = root.join("../SimdPaddleOCR/models");
    manifest.check_assets(&directory)?;
    let frames = baseline::decode_frames(&manifest, &root.join("tests/baseline"), true)?;
    let frame = frames
        .iter()
        .find(|f| f.id == fixture)
        .ok_or("unknown fixture")?;
    let spec = manifest
        .models
        .iter()
        .find(|m| m.id == model)
        .ok_or("unknown model")?;
    let settings = &manifest.settings;
    let import_start = Instant::now();
    let models = OcrModelSet::from_paths(
        directory.join(&spec.det),
        directory.join(&spec.rec),
        directory.join(&spec.dictionary),
        Some(&directory.join(&spec.cls)),
    )?;
    let import_ms = import_start.elapsed().as_secs_f64() * 1000.;
    let context_start = Instant::now();
    let cpu = Arc::new(CpuContext::new(CAPACITY)?);
    let context_ms = context_start.elapsed().as_secs_f64() * 1000.;
    let image = ImageView::new(
        &frame.pixels,
        frame.width as usize,
        frame.height as usize,
        0,
        PixelFormat::Bgr24,
    )?;
    let mut control = None;
    let mut cases = Vec::new();
    for (line_workers, batch_size) in owners
        .iter()
        .flat_map(|&owner| batch_sizes.iter().map(move |&batch| (owner, batch)))
    {
        check_deadline(started)?;
        let setup_start = Instant::now();
        let mut request = models
            .clone()
            .builder()
            .cpu_context(cpu.clone())
            .cpu_options(CpuOptions {
                line_workers,
                preprocess_workers: 0,
                detector_threads: 0,
            })
            .detector_options(DetectorOptions {
                limit_side_length: settings.detector_limit,
                max_candidates: settings.max_candidates,
                bitmap_threshold: settings.bitmap_threshold,
                box_threshold: Some(spec.box_threshold),
                unclip_ratio: settings.unclip_ratio,
                use_dilation: settings.use_dilation,
                ..Default::default()
            })
            .recognizer_options(RecognizerOptions {
                target_width: settings.target_width,
                adaptive_width: settings.adaptive_width,
                ..Default::default()
            })
            .line_options(LineOptions {
                classifier_threshold: settings.classifier_threshold,
                ..Default::default()
            })
            .direction_classification(settings.direction_classification)
            .recognition_batch_size(batch_size)
            .build()?;
        let compile_request_ms = setup_start.elapsed().as_secs_f64() * 1000.;
        let initial_budgets = format!("{:?}", request.cpu_budgets());
        check_deadline(started)?;
        if paired {
            event(&serde_json::json!({
                "event": "ready", "model": model, "fixture": fixture,
                "affinity": affinity, "pixel_sha256": baseline::hash(&frame.pixels),
                "manifest_sha256": baseline::hash(&std::fs::read(&manifest_path)?),
            }))?;
            command("warmup")?;
            check_deadline(started)?;
        }
        let warmup_start = Instant::now();
        let warmup = request.run(image, false)?.try_to_owned()?;
        let warmup_ms = warmup_start.elapsed().as_secs_f64() * 1000.;
        check_deadline(started)?;
        if let Some(expected) = &control {
            if &warmup != expected {
                return Err(
                    "ownership configurations produced different complete owned OCR results".into(),
                );
            }
        } else {
            control = Some(warmup);
        }
        if paired {
            event(&serde_json::json!({
                "event": "warmup", "milliseconds": warmup_ms,
                "output_sha256": baseline::hash(&serde_json::to_vec(control.as_ref().unwrap())?),
                "recognized_lines": control.as_ref().unwrap().lines.len(),
            }))?;
        }
        let line_count = control.as_ref().unwrap().lines.len();
        let classifier_worker_budget = if line_workers == 0 {
            CAPACITY.min(16)
        } else {
            line_workers.min(CAPACITY).min(16)
        };
        let mut wall_ms = Vec::new();
        let mut cpu_ms = Vec::new();
        for sample_index in 0..3 {
            if paired {
                command("run")?;
            }
            check_deadline(started)?;
            let cpu_start = benchmark::platform::process_cpu_time()?;
            let start = Instant::now();
            let output = request.run(image, false)?.try_to_owned()?;
            let elapsed_ms = start.elapsed().as_secs_f64() * 1000.;
            let elapsed_cpu_ms = benchmark::platform::process_cpu_time()?
                .checked_sub(cpu_start)
                .ok_or("process CPU time moved backwards")?
                .as_secs_f64()
                * 1000.;
            if Some(&output) != control.as_ref() {
                return Err("measured output differs from automatic warm-up control".into());
            }
            check_deadline(started)?;
            std::hint::black_box(&output);
            wall_ms.push(elapsed_ms);
            cpu_ms.push(elapsed_cpu_ms);
            if paired {
                event(&serde_json::json!({
                    "event": "sample", "sample_index": sample_index,
                    "milliseconds": elapsed_ms, "cpu_ms": elapsed_cpu_ms,
                    "output_sha256": baseline::hash(&serde_json::to_vec(&output)?),
                }))?;
            }
        }
        let (peak_private_bytes, peak_resident_bytes) = benchmark::platform::peak_memory()?;
        cases.push(serde_json::json!({
            "line_workers": line_workers,
            "recognition_batch_size": batch_size,
            "model_import_ms": import_ms,
            "cpu_context_ms": context_ms,
            "compile_request_ms": compile_request_ms,
            "initial_budgets": initial_budgets,
            "post_run_budgets": format!("{:?}", request.cpu_budgets()),
            "classifier_worker_budget_derived_from_policy": classifier_worker_budget,
            "active_classifier_workers_derived_from_policy": if settings.direction_classification { classifier_worker_budget.min(line_count) } else { 0 },
            "classifier_threads_per_worker": 1,
            "warmup_ms": warmup_ms,
            "samples_ms": wall_ms,
            "samples_cpu_ms": cpu_ms,
            "retained_activation_bytes": request.retained_activation_bytes(),
            "retained_workspace_bytes": request.retained_workspace_bytes(),
            "retained_kernel_scratch_bytes_subset_of_workspace": request.retained_kernel_scratch_bytes(),
            "process_peak_private_bytes": peak_private_bytes,
            "process_peak_resident_bytes": peak_resident_bytes,
        }));
    }
    check_deadline(started)?;
    let report = serde_json::json!({
        "event": "complete",
        "paired": paired,
        "instrumented": false,
        "model": model,
        "fixture": fixture,
        "cpu_context_capacity": CAPACITY,
        "affinity": affinity,
        "pixel_sha256": baseline::hash(&frame.pixels),
        "manifest_sha256": baseline::hash(&std::fs::read(manifest_path)?),
        "order": owners,
        "batch_size_order": batch_sizes,
        "warmups_per_configuration": 1,
        "measured_runs_per_configuration": 3,
        "capture_ctc_spans": false,
        "complete_owned_outputs_exactly_equal": true,
        "control_output_sha256": baseline::hash(&serde_json::to_vec(control.as_ref().unwrap())?),
        "recognized_lines": control.as_ref().unwrap().lines.len(),
        "cases": cases,
        "execution_seconds": started.elapsed().as_secs_f64(),
        "limitation": "One process and one configuration order; immutable models and a 24-thread CPU pool shared, fresh mutable request per configuration. The automatic setting uses 16 classifiers while explicit twelve owners uses twelve; classifier figures are derived from current source policy for one nonconcurrent request. Process memory peaks are cumulative high-water counters, not isolated request memory. Internal deadline checks cannot interrupt an in-flight OCR call. No steady-state or full qualification claim."
    });
    if paired {
        event(&report)?;
    } else {
        println!("{}", serde_json::to_string_pretty(&report)?);
    }
    Ok(())
}

fn main() {
    if let Err(error) = run() {
        eprintln!("CPU owner probe: {error}");
        std::process::exit(1);
    }
}

plan_probe_source:
//! Inspect selected kernels without running inference or collecting timings.
use sha2::{Digest, Sha256};
use simd_paddle_ocr_rs::{
    cpu::CpuContext,
    model::{Model, Operator},
    runtime::{CompiledModel, ExecutionOptions, Session},
};
use std::{path::PathBuf, sync::Arc};

fn run() -> Result<(), Box<dyn std::error::Error>> {
    let args: Vec<_> = std::env::args().skip(1).collect();
    if args.first().is_some_and(|a| a == "--help" || a == "-h") {
        println!(
            "cpu_plan_probe MODEL.onnx N,C,H,W [THREADS=1]\nCompile/bind only; report selected kernels and normalized 2x2 Conv inputs. No inference or performance samples."
        );
        return Ok(());
    }
    if !(2..=3).contains(&args.len()) {
        return Err("expected MODEL.onnx N,C,H,W [THREADS=1]".into());
    }
    let path = PathBuf::from(&args[0]).canonicalize()?;
    let shape = args[1]
        .split(',')
        .map(str::parse::<usize>)
        .collect::<Result<Vec<_>, _>>()?;
    let threads = args.get(2).map_or("1", String::as_str).parse::<usize>()?;
    let compiled = Arc::new(CompiledModel::new(Arc::new(Model::load_path(&path)?))?);
    let graph = compiled.model().graph();
    let conv_2x2: Vec<_> = graph.nodes.iter().enumerate().filter_map(|(index,node)| {
        let Operator::Conv(attributes) = &node.operator else { return None };
        if attributes.kernel_shape != [2,2] { return None; }
        let inputs: Vec<_> = node.inputs.iter().flatten().map(|id| {
            let tensor = &graph.tensors[id.0];
            serde_json::json!({"name":tensor.name,"constant_shape":tensor.constant.as_ref().map(|t|t.dimensions())})
        }).collect();
        Some(serde_json::json!({"node":index,"inputs":inputs,"pads":attributes.pads,"strides":attributes.strides}))
    }).collect();
    let session = Session::new(
        compiled,
        Arc::new(CpuContext::new(threads)?),
        &shape,
        ExecutionOptions {
            intra_op_threads: threads,
            ..Default::default()
        },
    )?;
    println!(
        "{}",
        serde_json::to_string_pretty(&serde_json::json!({
            "model_path":path,"model_sha256":format!("{:x}",Sha256::digest(std::fs::read(&path)?)),
            "input_shape":shape,"threads":threads,"inference_calls":0,
            "scope":"Complete graph compile/bind only, default automatic kernel/layout/fusion policies. Recognition production uses a prefix of this graph.",
            "normalized_conv_2x2":conv_2x2,"statistics":session.statistics(),
        }))?
    );
    Ok(())
}

fn main() {
    if let Err(error) = run() {
        eprintln!("Plan probe: {error}");
        std::process::exit(1);
    }
}
